"use client";

import * as React from "react";
import { motion, AnimatePresence } from "motion/react";

export function PortalRevealTailwind() {
  const [open, setOpen] = React.useState(true);
  return (
    <div className="space-y-3">
      <button type="button" onClick={() => setOpen(!open)} className="rounded bg-zinc-800 px-3 py-1 text-xs text-zinc-100">
        Toggle Portal
      </button>
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ clipPath: "circle(0% at 50% 50%)" }}
            animate={{ clipPath: "circle(140% at 50% 50%)" }}
            exit={{ clipPath: "circle(0% at 50% 50%)" }}
            transition={{ duration: 0.65, ease: [0.16, 1, 0.3, 1] }}
            className="rounded-xl border border-zinc-800 bg-zinc-900 p-5 text-zinc-100"
          >
            Radial Clip-Path Iris Portal
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
